order = self._repos['OrderRepository'].read_one(id=order_id)
    if order is None:
        raise errors.OrderNotFoundError
    for order_item in self._repos['OrderItemRepository'].read_all(order_id=order.id):
        product = self._repos['ProductRepository'].read_one(id=order_item.product_id)
        if product is None:
            raise errors.ProductNotFoundError
        if product.stock_quantity is None or product.stock_quantity < order_item.quantity:
            raise errors.InsufficientStockError
        self._repos['ProductRepository'].update(id=product.id, stock_quantity=product.stock_quantity + order_item.quantity)
